#define rot(x) mat2(cos(x+vec4(0,11,33,0)))
//formula for creating colors;
#define H(h)  ( cos( h/2. + (3.8+.5*sin(iTime))*vec3(2,3,4) )*.7 + .5 )
#define H2(h) ( cos( h*h/2. + vec3(1,2,0) )*.7 + .2 )
//formula for mapping scale factor 
#define M(c)  log(1.+c)
#define R iResolution
#define C(x) x = x>1. ? x=2.-x : (x<-1. ? -2.-x : x)

void mainImage( out vec4 O, vec2 U) {

    O = vec4(0);    
    vec3 c=vec3(0);
    vec4 rd = normalize( vec4(U-.5*R.xy, .8*R.y, R.y))*200.; 
    float sc,dotp,totdist=0.,t=mod(iTime,100.);  
    float iters = 8.;

    rd.xz *= rot(1.);

    for (float i=0.; i<30.; i++) {       
        vec4 p = vec4( rd*totdist);            
        p.xyz += vec3(3.6,5.7,1.5);        
        p.yzw = p.xyz;
        p.zw *= rot(1.57);
        p.xz = cos(p.xz/2.); 

        sc = 1.; 
        for (float j=0.; j<iters; j++) {
            C(p.x); C(p.y); C(p.z); C(p.w);  
            p *= .5;
            p -= .25*p;
            dotp = max(1./dot(p.xy,p.xy),.4);
            sc *= dotp;
            p = 1.9 *p * dotp ;                    
        }

        float dist = abs( length(p.zw)-.2)/sc ; 
        float stepsize = dist/100. ;     
        totdist += stepsize;                 

        c += (
               .03* H2(  atan( p.z, p.w ))  
             + .025* H(M(sc))
             ) * exp(-i*i*stepsize*stepsize*1e4);
    }

    c = 1. - exp(-c*c);
    O = ( vec4(c,0) );

}
